using System;
using System.IO;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using CashflowChains.City;
using CashflowChains.Economy;
using CashflowChains.Empire;
public sealed class CityBusinessDecisionsTests {
 BalanceConfig c;
 [SetUp]public void Setup(){c=JsonUtility.FromJson<BalanceConfig>(File.ReadAllText(Path.Combine(Application.dataPath,"_Game/Data/CC2/balance-v1.json")));c.Validate();}
 EmpireEngine Open(){var e=new EmpireEngine(c,new EmpireAccount{Economy=new EconomyState{AccountId="city-decisions"}},_=>true);e.OpenCity(100);e.BuildCity("cafe","cafe",2,1,101);e.FinishCityBuild("cafe",104);return e;}
 long AdvanceTo(EmpireEngine e,int day){long now=105;while(e.Snapshot.City.Day<day){e.StartCityDay(now);now+=c.City.DaySeconds(e.Snapshot.City.Day);e.SettleCityDay(e.Snapshot.City.Day,now);now++;}return now;}
 [Test]public void BuildingConsumesMaterialsAndARealBuilderRatherThanOnlyCash(){var e=Open();Assert.AreEqual(8,e.Snapshot.Economy.Amount("WOOD"));Assert.AreEqual(100,e.Snapshot.Economy.Amount("CASH"));e.BuildCity("house","home",0,1,105);Assert.AreEqual(2,e.Snapshot.Economy.Amount("WOOD"));Assert.AreEqual(1,e.Snapshot.City.Jobs.Count);}
 [Test]public void FinancingDisclosesFixedTermsAndRepaymentNeverCreatesCash(){var e=Open();long now=AdvanceTo(e,4);long cash=e.Snapshot.Economy.Amount("CASH");e.FinanceCity("loan",300,now);e.FinanceCity("loan",300,now);var loan=e.Snapshot.City.Loans.Single();Assert.AreEqual(cash+300,e.Snapshot.Economy.Amount("CASH"));Assert.AreEqual(30,loan.Fee);Assert.AreEqual(330,loan.Remaining);Assert.AreEqual(33,loan.Installment);e.RepayCityLoan("repay","loan",100,now);e.RepayCityLoan("repay","loan",100,now);Assert.AreEqual(230,e.Snapshot.City.Loans.Single().Remaining);Assert.AreEqual(cash+200,e.Snapshot.Economy.Amount("CASH"));Assert.Throws<ArgumentException>(()=>e.RepayCityLoan("too-much","loan",231,now));}
 [Test]public void ScheduledRepaymentsAreSeparateFromOperatingMarginAndExactlyOnce(){var e=Open();long now=AdvanceTo(e,4);e.FinanceCity("loan",300,now);e.StartCityDay(now);now+=c.City.DaySeconds(4);e.SettleCityDay(4,now);e.StartCityDay(now+1);var r=e.CurrentCityDay();Assert.AreEqual(33,r.LoanDue);Assert.AreEqual(r.OperatingNet-33,r.Net);long cash=e.Snapshot.Economy.Amount("CASH");e.SettleCityDay(5,now+1+c.City.DaySeconds(5));Assert.AreEqual(cash+r.Net,e.Snapshot.Economy.Amount("CASH"));Assert.AreEqual(297,e.Snapshot.City.Loans.Single().Remaining);}
 [Test]public void EarlyRepaymentDuringTradeCannotBeDebitedAgainAtClosing(){var e=Open();long now=AdvanceTo(e,4);e.FinanceCity("loan",100,now);e.StartCityDay(now);now+=c.City.DaySeconds(4);e.SettleCityDay(4,now);e.StartCityDay(now+1);e.RepayCityLoan("pay-full","loan",110,now+1);Assert.AreEqual(0,e.CurrentCityDay().LoanDue);long cash=e.Snapshot.Economy.Amount("CASH");var operating=e.CurrentCityDay().OperatingNet;e.SettleCityDay(5,now+1+c.City.DaySeconds(5));Assert.AreEqual(cash+operating,e.Snapshot.Economy.Amount("CASH"));}
 [Test]public void MoreEmployeesHaveWagesAndARealPopulationConstraint(){var e=Open();var before=e.ForecastCity();e.StaffCityBusiness("hire",2,3,105);var after=e.ForecastCity();Assert.Greater(after.Bills,before.Bills);Assert.AreEqual(80,e.Snapshot.Economy.Amount("CASH"));Assert.Throws<ArgumentException>(()=>e.StaffCityBusiness("invalid-staff",2,7,106));long now=AdvanceTo(e,4);e.BuildCity("farm","farm",0,1,now);e.FinishCityBuild("farm",now+8);Assert.Throws<InvalidOperationException>(()=>e.StaffCityBusiness("overhire",2,6,now+9));}
 [Test]public void AdvertisingCompetesForDemandButCannotInventResidentsOrUnlimitedCoffee(){var e=Open();long now=AdvanceTo(e,3);var before=e.ForecastCity();e.MarketCityBusiness("ads",2,15,now);var after=e.ForecastCity();Assert.AreEqual(before.CoffeeDemand,after.CoffeeDemand);Assert.AreEqual(before.Population,after.Population);Assert.LessOrEqual(after.CoffeeServed,after.CoffeeDemand);Assert.GreaterOrEqual(after.Bills,before.Bills+15);}
 [Test]public void SupplierAndSponsorshipAgreementsHaveCostsEvenWhenTargetsAreMissed(){var e=Open();long now=AdvanceTo(e,7);e.AgreeCityPartner("partner",false,now);e.AgreeCityPartner("sponsor",true,now);var r=e.ForecastCity();Assert.GreaterOrEqual(r.Bills,13);if(r.CoffeeServed<5)Assert.AreEqual(0,r.SponsorshipRevenue);Assert.AreEqual(9,e.Snapshot.City.SponsorEndsDay);}
 [Test]public void MaterialOrdersUseRealPricesAndCannotReplayOrCreateAnExchangeProfit(){var e=Open();long cash=e.Snapshot.Economy.Amount("CASH");e.BuyCityMaterials("timber","WOOD",2,105);e.BuyCityMaterials("timber","WOOD",2,105);Assert.AreEqual(cash-6,e.Snapshot.Economy.Amount("CASH"));Assert.AreEqual(10,e.Snapshot.Economy.Amount("WOOD"));foreach(var good in c.City.Goods)Assert.Less(good.ExportPrice,good.ImportPrice);}
 [Test]public void PendingMovesKeepCurrentTradingAtTheOldAddressAndApplyAtTheBoundary(){var e=Open();e.StartCityDay(105);e.MoveCityProperty("move",2,3,3,106);var p=e.Snapshot.City.Properties.Single(b=>b.Id==2);Assert.AreEqual(2,p.X);Assert.AreEqual(3,p.PendingX);e.SettleCityDay(1,110);e.StartCityDay(111);p=e.Snapshot.City.Properties.Single(b=>b.Id==2);Assert.AreEqual(3,p.X);Assert.AreEqual(-1,p.PendingX);}
}
